const PRIMARY_WRITE_CEIL = 30000; // writes/s on one primary
const PRIMARY_READ_CEIL  = 30000; // reads/s on one primary
const STORAGE_CEIL_TB    = 4;     // single-node storage ceiling

function decide({ writesPerSec, readsPerSec, datasetTB }) {
  // Writes and storage cannot be scaled out by replicas — only sharding splits them.
  const writesForceShard  = writesPerSec > PRIMARY_WRITE_CEIL;
  const storageForceShard = datasetTB    > STORAGE_CEIL_TB;
  if (writesForceShard || storageForceShard) {
    const reason = writesForceShard ? 'write throughput past single primary' : 'dataset past single-node storage';
    return `SHARD: ${reason}`;
  }
  // Writes/storage fit one primary. If reads alone exceed the primary, replicas absorb them.
  if (readsPerSec > PRIMARY_READ_CEIL) {
    return 'REPLICA: reads exceed one primary, but writes+storage fit';
  }
  return 'SCALE-UP: a single tuned primary still fits all dimensions';
}

const projected = { writesPerSec: 18000, readsPerSec: 120000, datasetTB: 1.2 };
console.log(decide(projected));
